const expr = 'Papayas';

beforeEach(() => {});

it('does something?', () => {
  switch (expr) {
    case 'Oranges':
      expect(expr).toBe('Oranges');

      break;
    case 'Mangoes':
    case 'Papayas':
      const v = 1;

      expect(v).toBe(1);

      console.log('Mangoes and papayas are $2.79 a pound.');
      // Expected output: "Mangoes and papayas are $2.79 a pound."
      break;
    default:
      console.log(`Sorry, we are out of ${expr}.`);
  }
});

