})

test('Regex', async () => {
  const throwErrorAsync = async () => { throw new Error('a') };
  await expect(throwErrorAsync()).rejects.toThrow(/^a$/);
  await expect(throwErrorAsync()).rejects.toThrowError(/^a$/);
})

